"""Writes build/generated_meta.txt during CI. The stamp format is
v<major>.<minor>.<patch>-<channel>."""

import pathlib
import subprocess
import sys


def write_stamp(version, channel):
    commit = subprocess.run(
        ["git", "rev-parse", "--short", "HEAD"], capture_output=True, text=True
    ).stdout.strip()
    out = pathlib.Path("build/generated_meta.txt")
    out.parent.mkdir(exist_ok=True)
    out.write_text(
        "# generated by scripts/stamp.py - do not edit\n"
        f"commit: {commit}\n"
        f"stamp: v{version}-{channel}\n"
    )


if __name__ == "__main__":
    write_stamp(sys.argv[1], sys.argv[2])
